import{z as i,x as B,o as e,c as d,q as r,j as n,D as E,d as l,s as A,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"风格控制","description":"","frontmatter":{"title":"风格控制","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/style-control.md","filePath":"llm/style-control.md","lastUpdated":1791413859000}'),p={name:"llm/style-control.md"};function m(c,a,D,h,C,u){const o=B("Mermaid");return e(),d("div",null,[a[2]||(a[2]=r('<h1 id="风格控制" tabindex="-1">风格控制 <a class="header-anchor" href="#风格控制" aria-label="Permalink to &quot;风格控制&quot;">​</a></h1><div class="epigraph"><p>人与法官都爱列表和长文。不把风格从偏好里拆开，Elo 测的是排版，不是任务完成。</p><footer>—— 对照 Dubois 等 AlpacaEval 的长度控制；Arena 后续的风格协变量</footer></div><p><a href="/llm/elo-bt-rating">上一课</a>承认未控风格时强度含混淆。本课写控制。缺口是：截断再评、回归去长度、或强制短答，会改名次——那才说明原榜吃了风格。后课自我偏好是风格混淆的一种族谱特例。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Dubois 等人在 AlpacaEval 2.0 里展示：长度与胜率强相关，控制长度后许多「领先」缩小或翻转。Arena 加风格特征（长度、markdown 元素）进回归，得到「风格控制后的 Elo」。不控制时，RLHF 对冗长的奖励与评测仪器同构，优化器在刷仪器。</p><p>控制不是「风格无价值」。产品若真要健谈助手，应把健谈写成声明，用显式指标，而不是让它偷走「更正确」的名次。</p><p><span class="marginnote">简单截断会误伤需要长文的任务（代码补全、合同条款）。应按任务设长度预算，或在回归里把长度当协变量，而不是全局砍到 200 词。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三种互补。<strong>截断</strong>：两条回复裁到同一 token 预算再送法官或人。<strong>回归</strong>：在 BT 里加长度等协变量，报告受控 \\(s\\)。<strong>分层</strong>：按任务类型分别排名。<span class="marginnote">「把长度当协变量」翻译一下：不是把长回答扔掉不算，而是在统计模型里先回答一个反事实问题——「假如两条回复一样长，谁更可能被选中」。估计出的就是这个修正后的胜负倾向，长度本身的加分被显式记账，不再混进能力分。</span>AlpacaEval 的长度控制胜率是回归路线的一个实现，换数据集不要照抄系数。</p><p>与<a href="/llm/length-penalty-degeneration">长度惩罚</a>课对照：解码侧惩罚长度是生成策略；本课是评测侧不让长度决定名次。两边可以同时做，声明要分开。</p>',10)),(e(),n(s,null,{default:E(()=>[A(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E5%9B%9E%E5%A4%8D%22%5D%20--%3E%20LEN%5B%22%E9%95%BF%E5%BA%A6%20%2F%20markdown%20%E7%89%B9%E5%BE%81%22%5D%0A%20%20Y%20--%3E%20RAW%5B%22%E6%9C%AA%E6%8E%A7%20Elo%22%5D%0A%20%20LEN%20--%3E%20CTL%5B%22%E5%8D%8F%E5%8F%98%E9%87%8F%E6%88%96%E6%88%AA%E6%96%AD%22%5D%0A%20%20CTL%20--%3E%20ADJ%5B%22%E5%8F%97%E6%8E%A7%E5%BC%BA%E5%BA%A6%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[l("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"偏好模型（人脑或 LLM 法官）把「看起来费了工夫」当质量代理。长度是最廉价的工夫信号。控制相当于在估计里偏掉这条代理，逼迫剩余胜负来自内容。若控制后名次坍缩，说明原差距主要是代理；若名次稳定，说明内容差够大。两种结果都是信息，不要只发表稳定的那种。",-1)),(e(),n(s,null,{default:E(()=>[A(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAIR%5B%22%E5%90%8C%E4%B8%80%E5%AF%B9%E5%9B%9E%E5%A4%8D%20%E5%85%88%E8%AE%B0%E5%8E%9F%E5%A7%8B%E8%83%9C%E8%B4%9F%22%5D%20--%3E%20CTL%5B%22%E6%96%BD%E5%8A%A0%E9%A3%8E%E6%A0%BC%E6%8E%A7%E5%88%B6%20%E5%90%8C%E9%A2%84%E7%AE%97%E6%88%96%E5%8A%A0%E5%8D%8F%E5%8F%98%E9%87%8F%22%5D%0A%20%20CTL%20--%3E%20R%7B%22%E5%8F%97%E6%8E%A7%E5%90%8E%E5%90%8D%E6%AC%A1%E6%80%8E%E6%A0%B7%3F%22%7D%0A%20%20R%20--%3E%7C%22%E9%A2%86%E5%85%88%E4%BF%9D%E6%8C%81%22%7C%20REAL%5B%22%E5%86%85%E5%AE%B9%E5%B7%AE%E7%9C%9F%E5%AE%9E%20%E5%8F%AF%E4%BF%A1%22%5D%0A%20%20R%20--%3E%7C%22%E7%BC%A9%E5%B0%8F%E6%88%96%E7%BF%BB%E8%BD%AC%22%7C%20PROXY%5B%22%E5%8E%9F%E5%B7%AE%E8%B7%9D%E4%B8%BB%E8%A6%81%E6%98%AF%E9%A3%8E%E6%A0%BC%E4%BB%A3%E7%90%86%22%5D%0A%20%20PROXY%20--%3E%20ACT%5B%22%E6%94%B9%E5%86%99%E6%8A%A5%E5%91%8A%20%E6%8C%89%E4%BB%BB%E5%8A%A1%E5%A3%B0%E6%98%8E%E9%A3%8E%E6%A0%BC%E9%A2%84%E7%AE%97%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">数字实例：设模型 A 平均写 800 token、模型 B 写 400 token，原始对局 A 胜率 70%。长度控制等于追问「若两者都只写 400 token，谁赢」——胜率可能掉到 55%。缩水的那 15 个点，就是 A 一直在用篇幅向法官「交房租」，而不是靠内容赢。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>过度控制会把合法的详尽解释当作弊。应预先规定：哪些任务允许长、哪些任务风格应中性。<span class="marginnote">常见误区：看到某模型「风格控制后 Elo 掉了很多」就断定它退步了。受控分数与未控分数不可直接横比，受控 Elo 只在同榜、同控制方式内部比名次；掉分真正的含义是「它此前的领先里有多大比例来自排版」。</span>下一课自我偏好：即使长度相同，法官仍可能偏爱「像自己」的句子。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>长度与列表是偏好评测的一等混淆，必须控制或分声明。</li><li>截断、协变量、按任务分层可并用，系数不可跨库照抄。</li><li>控制后名次翻转是有效发现，不是事故。</li><li>出处：Dubois 等 AlpacaEval 2.0；Arena 风格控制实践。</li></ul>',5))])}const F=i(p,[["render",m]]);export{f as __pageData,F as default};
